int *data = malloc(10 * sizeof(int));
size_t new_size = 20 * sizeof(int);

// Safe Reallocation Pattern
int *temp_ptr = realloc(data, new_size);

if (temp_ptr == NULL) {
    // Failure: data pointer is unchanged and valid.
    // Memory leak prevented.
    free(data); // Must still free original block if aborting.
} else {
    // Success: safely update the original pointer.
    data = temp_ptr;
}

// data now points to the larger (or original) block.
